fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    let mut result = Vec::with_capacity(a.len());
    
    for s in a {
        let mut inner_list = Vec::new();
        
        if keepends {
            // When keepends is true, we keep the line endings
            // For simplicity, we'll split on newline but include it
            let lines: Vec<String> = s
                .split_inclusive('\n')
                .map(|line| line.to_string())
                .collect();
            
            if lines.is_empty() {
                // If the string is empty, we still need a non-empty inner list
                inner_list.push(String::new());
            } else {
                inner_list = lines;
            }
        } else {
            // When keepends is false, we don't keep line endings
            let lines: Vec<String> = s
                .split('\n')
                .map(|line| line.to_string())
                .collect();
            
            if lines.is_empty() {
                // If the string is empty, we still need a non-empty inner list
                inner_list.push(String::new());
            } else {
                inner_list = lines;
            }
        }
        
        result.push(inner_list);
    }
    
    result
}